import random


def strategy(history, rng):
    if not history:
        return 'C'

    n = len(history)
    my_last, opp_last = history[-1]
    my_total = sum(1 for a, _ in history if a == 'C')
    opp_defections = sum(1 for _, b in history if b == 'D')
    opp_cooperations = n - opp_defections

    if n <= 3:
        return 'C' if opp_last == 'C' else 'D'

    recent = history[-4:]
    opp_recent_defections = sum(1 for _, b in recent if b == 'D')
    opp_recent_cooperations = len(recent) - opp_recent_defections
    my_recent_defections = sum(1 for a, _ in recent if a == 'D')

    if n >= 6:
        last8 = history[-8:]
        opp_last8_def = sum(1 for _, b in last8 if b == 'D')
        if opp_last8_def >= 6:
            return 'D'
        if opp_last8_def <= 1:
            return 'C'

    if n >= 10:
        opp_rate = opp_cooperations / n
        if opp_rate < 0.2:
            return 'D'
        if opp_rate > 0.85:
            return 'C'

    total_score = 0
    for a, b in history:
        if a == 'C' and b == 'C':
            total_score += 3
        elif a == 'D' and b == 'C':
            total_score += 5
        elif a == 'D' and b == 'D':
            total_score += 1

    if n >= 10:
        opp_defections_last10 = sum(1 for _, b in history[-10:] if b == 'D')
        if opp_defections_last10 >= 5:
            if rng.random() < 0.7:
                return 'D'

    if opp_last == 'D':
        if recent and opp_recent_defections >= 3:
            return 'D'
        if n > 5 and rng.random() < 0.35:
            return 'C'
        return 'D'

    if opp_last == 'C':
        if recent and my_recent_defections >= 3:
            return 'C'
        if n > 8 and rng.random() < 0.05:
            return 'D'
        return 'C'

    return 'C'
